function VehicleType(Name)
	return VehicleTypes[Name]
end
-----------------------------------------------------------------------------------------------------------------------------------------
-- QG_SYSTEM
-----------------------------------------------------------------------------------------------------------------------------------------
CreateThread(function()
    local Configs = exports["org_system"]:GetAllOfConfig("GARAGES")
    for i=1,#Configs do
        local Config = Configs[i]
        for j=1,#Config do
            table.insert(Garages,Config[j])
        end
    end
end)

function GetGarages()
    return Garages
end
exports("GetGarages",GetGarages)